import math

def build_agent(sandbox):
    # No specific structure needed; robot is already defined
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    # Initialize attributes if not present
    if not hasattr(agent_body, 'unlock_steps'):
        agent_body.unlock_steps = 0
    if not hasattr(agent_body, 'unlocked'):
        agent_body.unlocked = False
    if not hasattr(agent_body, 'exit_hold_steps'):
        agent_body.exit_hold_steps = 0

    # Get whisker readings
    front, up, down = sandbox.get_whisker_readings()
    # Get position
    pos = sandbox.get_agent_position()
    x, y = pos
    # Get velocity
    vel = sandbox.get_agent_velocity()
    speed = math.hypot(vel[0], vel[1])

    # Check if in unlock zone
    if 5.0 <= x <= 10.0:
        # Check if unlocked
        if not agent_body.unlocked:
            # Apply unlock force
            sandbox.apply_agent_force(-35.0, 0.0)
            # Check speed condition
            if speed < 100.0:
                agent_body.unlock_steps += 1
                # Check if unlock_steps >=5
                if agent_body.unlock_steps >= 5:
                    agent_body.unlocked = True
                    # After unlocking, apply forward force to reach exit
                    sandbox.apply_agent_force(20.0, 0.0)
                    agent_body.unlock_steps = 0
            else:
                # Speed is too high, reset unlock steps
                agent_body.unlock_steps = 0
        else:
            # Already unlocked, move towards exit
            if x >= 15.0 and 0.5 <= y <= 2.5:
                # Hold position
                sandbox.apply_agent_force(0.0, 0.0)
                agent_body.exit_hold_steps += 1
                if agent_body.exit_hold_steps >= 5:
                    # Exit hold complete
                    pass
            else:
                # Move towards exit
                sandbox.apply_agent_force(20.0, 0.0)
                agent_body.exit_hold_steps = 0
    else:
        # Not in unlock zone, navigate using whiskers
        # Set threshold for whisker readings
        threshold = 1.0
        if front < threshold:
            # Wall in front, move backward
            sandbox.apply_agent_force(-20.0, 0.0)
        else:
            # Check up and down whiskers
            if up < threshold:
                # Wall above, move down
                sandbox.apply_agent_force(0.0, -20.0)
            elif down < threshold:
                # Wall below, move up
                sandbox.apply_agent_force(0.0, 20.0)
            else:
                # No walls detected, move forward
                sandbox.apply_agent_force(20.0, 0.0)

